    torch::Tensor output, int64_t block_size);

namespace {

void check_cusolver(cusolverStatus_t status, const char* what) {
    TORCH_CHECK(status == CUSOLVER_STATUS_SUCCESS, what, " failed with status ",
                static_cast<int>(status));
}

void check_cublas(cublasStatus_t status, const char* what) {
    TORCH_CHECK(status == CUBLAS_STATUS_SUCCESS, what, " failed with status ",
                static_cast<int>(status));
}

} // namespace

torch::Tensor direct_cholesky(
        torch::Tensor input,
        torch::Tensor output,
        torch::Tensor pointers,
        torch::Tensor info,
        torch::Tensor workspace) {
    TORCH_CHECK(input.is_cuda(), "input must be CUDA");
    TORCH_CHECK(input.scalar_type() == at::kFloat, "input must be float32");
    TORCH_CHECK(input.is_contiguous(), "input must be contiguous");
    TORCH_CHECK(input.dim() == 3 && input.size(1) == input.size(2),
                "input must be a batch of square matrices");
    TORCH_CHECK(output.is_cuda() && output.scalar_type() == at::kFloat,
                "output must be CUDA float32");
    TORCH_CHECK(output.is_contiguous() && output.sizes() == input.sizes(),
                "output must be a same-sized contiguous tensor");

    const int batch = static_cast<int>(input.size(0));
    const int n = static_cast<int>(input.size(1));
    // cuSOLVER's column-major lower triangle is the row-major upper triangle.
    // Copy just that source triangle and zero the unused half in one kernel.
    at::triu_out(output, input, 0);
    TORCH_CHECK(info.is_cuda() && info.scalar_type() == at::kInt &&
                info.numel() == batch, "invalid info tensor");
    auto handle = at::cuda::getCurrentCUDASolverDnHandle();
    check_cusolver(
        cusolverDnSetMathMode(handle, CUSOLVER_FP32_EMULATED_BF16X9_MATH),
        "cusolverDnSetMathMode");

    const bool use_looped = batch <= 4 && n >= 1024;
    if (!use_looped) {
        TORCH_CHECK(pointers.is_cuda() &&
                    pointers.scalar_type() == at::kLong &&
                    pointers.numel() == batch, "invalid pointer array");
        check_cusolver(
            cusolverDnSpotrfBatched(
                handle, CUBLAS_FILL_MODE_LOWER, n,
                reinterpret_cast<float**>(pointers.data_ptr<int64_t>()), n,
                info.data_ptr<int>(), batch),
            "cusolverDnSpotrfBatched");
    } else {
        TORCH_CHECK(workspace.is_cuda() &&
                    workspace.scalar_type() == at::kFloat,
                    "invalid workspace tensor");
        const int64_t matrix_stride = static_cast<int64_t>(n) * n;
        for (int i = 0; i < batch; ++i) {
            check_cusolver(
                cusolverDnSpotrf(
                    handle, CUBLAS_FILL_MODE_LOWER, n,
                    output.data_ptr<float>() + i * matrix_stride, n,
                    workspace.data_ptr<float>(), workspace.numel(),
                    info.data_ptr<int>() + i),
                "cusolverDnSpotrf");
        }
    }

    // The row-major upper factor becomes an F-contiguous lower-triangular view.
    return output.transpose(-2, -1);
}

torch::Tensor grouped_blocked_cholesky(
        torch::Tensor input,
        torch::Tensor output,
        torch::Tensor pointers,
        torch::Tensor info,
        int64_t block_size) {
    TORCH_CHECK(input.is_cuda() && output.is_cuda(), "CUDA tensors required");
    TORCH_CHECK(input.scalar_type() == at::kFloat &&
                output.scalar_type() == at::kFloat, "FP32 tensors required");
    TORCH_CHECK(input.is_contiguous() && output.is_contiguous() &&
                input.sizes() == output.sizes(), "invalid matrix buffers");
    TORCH_CHECK(input.dim() == 3 && input.size(1) == input.size(2),
                "square matrix batches required");

    const int batch = static_cast<int>(input.size(0));
    const int n = static_cast<int>(input.size(1));
    const int block = static_cast<int>(block_size);
    const int panels = (n + block - 1) / block;
    TORCH_CHECK(block > 0 && block <= n, "invalid block size");
    TORCH_CHECK(pointers.is_cuda() &&
                pointers.scalar_type() == at::kLong &&
                pointers.numel() == static_cast<int64_t>(panels) * 2 * batch,
                "invalid grouped pointer tables");
    TORCH_CHECK(info.is_cuda() && info.scalar_type() == at::kInt &&
                info.numel() == batch, "invalid info tensor");

    // Treat row-major upper storage as column-major lower storage.
    at::triu_out(output, input, 0);
    auto solver = at::cuda::getCurrentCUDASolverDnHandle();
    auto blas = at::cuda::getCurrentCUDABlasHandle();
    check_cusolver(
        cusolverDnSetMathMode(solver, CUSOLVER_FP32_EMULATED_BF16X9_MATH),
        "cusolverDnSetMathMode");

    const float one = 1.0f;
    const float minus_one = -1.0f;
    const int64_t matrix_stride = static_cast<int64_t>(n) * n;
    auto pointer_data = pointers.data_ptr<int64_t>();
    float* output_data = output.data_ptr<float>();

    for (int panel_index = 0, k = 0; k < n;
         ++panel_index, k += block) {
        const int width = std::min(block, n - k);
        const int stop = k + width;
        float** diagonal = reinterpret_cast<float**>(
            pointer_data + static_cast<int64_t>(panel_index) * 2 * batch
        );
        check_cusolver(
            cusolverDnSpotrfBatched(
                solver, CUBLAS_FILL_MODE_LOWER, width, diagonal, n,
                info.data_ptr<int>(), batch),
            "grouped diagonal potrf");
        if (stop == n) {
            continue;
        }

        const int trailing = n - stop;
        float* const* panel = reinterpret_cast<float* const*>(
            pointer_data +
            static_cast<int64_t>(panel_index) * 2 * batch + batch
        );
        check_cublas(
            cublasStrsmBatched(
                blas, CUBLAS_SIDE_RIGHT, CUBLAS_FILL_MODE_LOWER,
                CUBLAS_OP_T, CUBLAS_DIAG_NON_UNIT,
                trailing, width, &one,
                reinterpret_cast<const float* const*>(diagonal), n,
                panel, n, batch),
            "grouped panel trsm");

        float* first_panel = output_data +
            static_cast<int64_t>(k) * n + stop;
        float* first_trailing = output_data +
            static_cast<int64_t>(stop) * n + stop;
        check_cublas(
            cublasGemmStridedBatchedEx(
                blas, CUBLAS_OP_N, CUBLAS_OP_T,
                trailing, trailing, width,
                &minus_one,
                first_panel, CUDA_R_32F, n, matrix_stride,
                first_panel, CUDA_R_32F, n, matrix_stride,
                &one,
                first_trailing, CUDA_R_32F, n, matrix_stride,
                batch, CUBLAS_COMPUTE_32F_FAST_TF32,
                CUBLAS_GEMM_DEFAULT_TENSOR_OP),
            "grouped trailing gemm");
    }

    // Full GEMMs touched both halves; retain only the physical upper factor.
    at::triu_out(output, output, 0);
    return output.transpose(-2, -1);
}

void fp16_update_(torch::Tensor trailing, torch::Tensor panel) {
    TORCH_CHECK(trailing.is_cuda() && panel.is_cuda(), "CUDA tensors required");
    TORCH_CHECK(trailing.scalar_type() == at::kFloat,
                "FP32 trailing matrix required");
    TORCH_CHECK(panel.scalar_type() == at::kHalf,
                "FP16 panel required");
    TORCH_CHECK(trailing.dim() == 3 && panel.dim() == 3,
                "batched matrices required");

    const int batch = static_cast<int>(panel.size(0));
    const int n = static_cast<int>(panel.size(1));
    const int k = static_cast<int>(panel.size(2));
    const int lda = static_cast<int>(panel.stride(1));
    const int ldc = static_cast<int>(trailing.stride(1));
    const int64_t panel_batch_stride = panel.stride(0);
    const int64_t trailing_batch_stride = trailing.stride(0);
    const float alpha = -1.0f;
    const float beta = 1.0f;

    auto handle = at::cuda::getCurrentCUDABlasHandle();
    check_cublas(
        cublasGemmStridedBatchedEx(
            handle, CUBLAS_OP_T, CUBLAS_OP_N, n, n, k,
            &alpha,
            panel.data_ptr<at::Half>(), CUDA_R_16F, lda,
            panel_batch_stride,
            panel.data_ptr<at::Half>(), CUDA_R_16F, lda,
            panel_batch_stride,
            &beta,
            trailing.data_ptr<float>(), CUDA_R_32F, ldc,
            trailing_batch_stride,
            batch, CUBLAS_COMPUTE_32F, CUBLAS_GEMM_DEFAULT),
        "cublasGemmStridedBatchedEx");
}

void trsm_(torch::Tensor factor, torch::Tensor panel) {
    TORCH_CHECK(factor.is_cuda() && panel.is_cuda(), "CUDA tensors required");
    TORCH_CHECK(factor.scalar_type() == at::kFloat &&
                panel.scalar_type() == at::kFloat,
                "FP32 factor and panel required");
    TORCH_CHECK(factor.dim() == 3 && panel.dim() == 3 &&
                factor.size(0) == 1 && panel.size(0) == 1,
                "single batched matrices required");
    TORCH_CHECK(factor.size(1) == factor.size(2) &&
                panel.size(2) == factor.size(1),
                "incompatible triangular solve shapes");

    const int k = static_cast<int>(factor.size(1));
    const int m = static_cast<int>(panel.size(1));
    TORCH_CHECK(factor.stride(1) == 1,
                "column-major triangular factor required");
    const int lda = static_cast<int>(factor.stride(2));
    const int ldb = static_cast<int>(panel.stride(1));
    const float alpha = 1.0f;
    auto handle = at::cuda::getCurrentCUDABlasHandle();
    check_cublas(
        cublasStrsm(
            handle, CUBLAS_SIDE_LEFT, CUBLAS_FILL_MODE_LOWER,
            CUBLAS_OP_N, CUBLAS_DIAG_NON_UNIT, k, m, &alpha,
            factor.data_ptr<float>(), lda, panel.data_ptr<float>(), ldb),
        "cublasStrsm");
}

void lower_copy_(torch::Tensor input, torch::Tensor output);
void copy_factor_lower_(torch::Tensor factor, torch::Tensor output);

int64_t workspace_size(torch::Tensor input) {
    const int n = static_cast<int>(input.size(-1));
    int lwork = 0;
    auto handle = at::cuda::getCurrentCUDASolverDnHandle();
    check_cusolver(
        cusolverDnSetMathMode(handle, CUSOLVER_FP32_EMULATED_BF16X9_MATH),
        "cusolverDnSetMathMode");
    check_cusolver(
        cusolverDnSpotrf_bufferSize(
            handle, CUBLAS_FILL_MODE_LOWER, n, input.data_ptr<float>(), n,
            &lwork),
        "cusolverDnSpotrf_bufferSize");
    return lwork;
}

