    torch::Tensor panel,
    torch::Tensor pointers);
void convert_batch_panel_cuda(
    torch::Tensor panel, torch::Tensor converted);
void batch_lower_copy_cuda(
    torch::Tensor input, torch::Tensor output);

void batch_panel_solve_(
    torch::Tensor factor,
    torch::Tensor panel,
    torch::Tensor pointers
) {
    TORCH_CHECK(factor.is_cuda() && panel.is_cuda(), "CUDA tensors required");
    TORCH_CHECK(
        factor.scalar_type() == at::kFloat
        && panel.scalar_type() == at::kFloat,
        "FP32 tensors required"
    );
    TORCH_CHECK(
        factor.dim() == 3 && panel.dim() == 3
        && factor.size(0) == panel.size(0)
        && factor.size(1) == factor.size(2)
        && factor.size(1) == panel.size(2),
        "invalid factor/panel shapes"
    );
    TORCH_CHECK(panel.stride(2) == 1, "panel columns must be contiguous");

    const int batch = static_cast<int>(factor.size(0));
    const int k = static_cast<int>(factor.size(1));
    const int columns = static_cast<int>(panel.size(1));
    cublasFillMode_t uplo;
    int lda;
    if (factor.stride(1) == 1) {
        uplo = CUBLAS_FILL_MODE_LOWER;
        lda = static_cast<int>(factor.stride(2));
    } else {
        TORCH_CHECK(
            factor.stride(2) == 1,
            "factor must be row-major or column-major contiguous"
        );
        uplo = CUBLAS_FILL_MODE_UPPER;
        lda = static_cast<int>(factor.stride(1));
    }
    const int ldb = static_cast<int>(panel.stride(1));
    const float alpha = 1.0f;
    TORCH_CHECK(
        pointers.is_cuda() && pointers.scalar_type() == at::kLong
        && pointers.numel() == 2 * batch,
        "invalid TRSM pointer storage"
    );
    auto factor_pointers = reinterpret_cast<const float* const*>(
        pointers.data_ptr<int64_t>()
    );
    auto panel_pointers = reinterpret_cast<float* const*>(
        pointers.data_ptr<int64_t>() + batch
    );
    auto handle = at::cuda::getCurrentCUDABlasHandle();
    check_cublas(
        cublasStrsmBatched(
            handle,
            CUBLAS_SIDE_LEFT,
            uplo,
            CUBLAS_OP_N,
            CUBLAS_DIAG_NON_UNIT,
            k,
            columns,
            &alpha,
            factor_pointers,
            lda,
            panel_pointers,
            ldb,
            batch
        ),
        "cublasStrsmBatched"
    );
}

void batch_panel_step_(
    torch::Tensor factor,
    torch::Tensor diagonal,
    torch::Tensor panel,
    torch::Tensor converted,
    torch::Tensor trailing,
    torch::Tensor pointers
) {
    prepare_batch_factor_and_pointers_cuda(
        factor, diagonal, panel, pointers
    );
    batch_panel_solve_(factor, panel, pointers);
    convert_batch_panel_cuda(panel, converted);
    fp16_update_(trailing, converted);
}

int64_t workspace_size(torch::Tensor input) {
    const int n = static_cast<int>(input.size(-1));
    int lwork = 0;
    auto handle = at::cuda::getCurrentCUDASolverDnHandle();
    check_cusolver(
        cusolverDnSetMathMode(handle, CUSOLVER_FP32_EMULATED_BF16X9_MATH),
        "cusolverDnSetMathMode");
    check_cusolver(
        cusolverDnSpotrf_bufferSize(
            handle, CUBLAS_FILL_MODE_LOWER, n, input.data_ptr<float>(), n,
            &lwork),
        "cusolverDnSpotrf_bufferSize");
    return lwork;
}

